const owner=installDevelopmentProcessLifecycle({label:'SSR concurrency profiles',close});
async function traffic(c,ms){for(let i=0;i<2;i++)drivers.push(await startSsrLoadProcess('driver'));for(const d of drivers)d.run({url:worker.url+'?__benchmarkPreloaded=true',stages:[{name:'profile-c'+c,mode:'concurrency',concurrency:c/2,durationMs:ms}]});const results=await Promise.race([Promise.all(drivers.map(d=>d.result)),service.result]);await closeDrivers();return results;}
