fs.writeFileSync('docs/performance-baselines/ssr-followthrough-2026-09-07.json',JSON.stringify(archive)+'\n');fs.writeFileSync('docs/performance-baselines/ssr-followthrough-capacity-2026-09-07.json',JSON.stringify(capacity)+'\n');console.log('Archive and accounting assertions passed');

