import {readFile,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {installDevelopmentProcessLifecycle} from '../../scripts/development-process-lifecycle.mjs';
import {startSsrLoadProcess} from '../../framework-comparison/src/ssr-load-process-owner.mjs';
import {startSsrWorker,stopSsrWorker,controlSsrWorker} from '../../framework-comparison/src/ssr-worker-controller.mjs';
import {availableSsrRuntimes} from '../../framework-comparison/src/ssr-run-environment.mjs';
const plan=JSON.parse(await readFile(process.argv[2],'utf8')),output=process.argv[3];
const prior=JSON.parse(await readFile('.tmp/ssr-preloaded/sweep.json','utf8'));
const report={kind:'multi-driver-preloaded-ssr',complete:false,createdAt:new Date().toISOString(),plan,artifacts:prior.artifacts,environment:prior.environment,blocks:[],runner:await readFile(import.meta.filename,'utf8')};
const runtime=availableSsrRuntimes('node')[0];let service,worker,drivers=[],timer,polling;
