import fs from 'node:fs';import assert from 'node:assert/strict';import{createHash}from'node:crypto';import{profileNodeCpu,profileNodeAllocations}from'../../framework-comparison/src/ssr-allocation-profiler.mjs';
const baselineRender=await import('./baseline.mjs'); const projectorRender=await import('./'+process.argv[3]+'.mjs');const data=JSON.parse(fs.readFileSync('.tmp/ssr-followthrough/data.json'));
const variants=[];for(const name of ['baseline','projector'])variants.push({name,...await import('./baseline-body.mjs'),...await import('./baseline-handler.mjs')});
const headers={'content-type':'text/html; charset=utf-8','cache-control':'no-store'};let bytes,hash;
