for(const v of variants)await run(v,8000);
const rows=[];for(let round=0;round<24;round++){const vs=[...variants.slice(round%2),...variants.slice(0,round%2)];if(round%2)vs.reverse();for(const v of vs)rows.push({round,name:v.name,...await run(v,2000)});}
for(const row of rows)assert.equal(row.hash,rows[0].hash);
const profile=process.argv.includes('--profile')?{cpu:await profileNodeCpu(()=>run(variants[0],20000)),allocation:await profileNodeAllocations(()=>run(variants[0],10000))}:undefined;
fs.writeFileSync(process.argv[2],JSON.stringify({rows,profile}));for(const v of variants)console.log(v.name,rows.filter(r=>r.name===v.name).reduce((n,r)=>n+r.elapsedMs,0)/48,'us/request');

